function journalForm(record){const r=record||{id:'',date:localDateTime(),phase:'Wait and Observe',price:'',horizon:'30',title:'',evidence:'',action:'',review:''};for(const k of ['id','date','phase','price','horizon','title','evidence','action','review'])$('journal'+k[0].toUpperCase()+k.slice(1)).value=r[k]??'';$('journalDirection').value=r.direction||'';$('journalEditorTitle').textContent=record?'Edit decision':'New decision'}
function localDateTime(){const date=new Date();return new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16)}
function renderJournal(){const sorted=[...state.journal].sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))||(Number(b.createdAt)||Number(b.id?.split('-')[0])||0)-(Number(a.createdAt)||Number(a.id?.split('-')[0])||0));$('journalCount').textContent=sorted.length+' entries';$('journalList').replaceChildren();if(!sorted.length){$('journalList').innerHTML='<div class="plot-placeholder">No decisions yet. Add your first research entry.</div>';return}sorted.forEach(r=>{const node=document.createElement('div');node.className='journal-entry';const title=document.createElement('strong');title.textContent=r.title||'제목 None';const meta=document.createElement('div');meta.className='meta';meta.textContent=r.date+' · '+r.phase+(Number(r.price)>0?' · '+money(r.price):'');const p=document.createElement('p');p.textContent=(r.evidence||'').slice(0,260)||'No supporting rationale';const actions=document.createElement('div');actions.className='actions';actions.append(btn('Edit',()=>{journalForm(r);window.scrollTo({top:0,behavior:'smooth'})}),btn('Delete',()=>{if(confirm('이 판단 기록을 Delete할까?')){state.journal=state.journal.filter(e=>e.id!==r.id);persist();renderJournal();renderOverview()}},'secondary remove'));node.append(title,meta,p,actions);$('journalList').append(node)})}
function initJournal(){journalForm();$('saveJournal').onclick=()=>{const r={};for(const k of ['id','date','phase','price','horizon','title','evidence','action','review'])r[k]=$('journal'+k[0].toUpperCase()+k.slice(1)).value;if(!r.title.trim())return toast('Enter a decision title.');if(!r.date)return toast('Choose a date and time for your decision.');r.direction=$('journalDirection').value;if(!r.id){r.id=String(Date.now())+'-'+Math.floor(Math.random()*10000);r.createdAt=Date.now()}else{r.createdAt=state.journal.find(e=>e.id===r.id)?.createdAt||Number(r.id.split('-')[0])||Date.now()}if(state.journal.some(e=>e.id===r.id))state.journal=state.journal.map(e=>e.id===r.id?r:e);else state.journal.push(r);persist(true);renderJournal();renderOverview();journalForm()};$('cancelJournal').onclick=()=>journalForm();$('useCurrentPrice').onclick=()=>{if(!price)return toast('BTC price is not connected. Enter a reference price manually.');$('journalPrice').value=price.value;toast('Current BTC quote copied into the form.')};$('exportJournal').onclick=()=>{const keys=['date','title','phase','price','horizon','evidence','action','review'];const csv=[keys.join(','),...state.journal.map(r=>keys.map(k=>'"'+String(r[k]??'').replaceAll('"','""')+'"').join(','))].join('\r\n');download('cycle-journal.csv','\uFEFF'+csv,'text/csv')}}
function renderSources(){if(!$('dataSources'))return;const list=[['TradingView Charts','Chart 임베드 (외부 서버)'],['BTC spot price (5-second polling)',fetched.price||'Not fetched'],['Alternative.me Fear·Greed',fetched.fear||'Not fetched'],['Binance Funding Rate',fetched.funding||'Not fetched'],['Binance Open Interest',fetched.oi||'Not fetched'],['BTC/USD historical close',fetched.history||(history.length?'Local historical observations: '+history.length+' records':'Not fetched')],['BTC 네트워크 blocks 높이',fetched.block||'Not fetched'],['ETF and institutional holdings',fetched.institution||'Dated snapshots'],['MVRV / SOPR / Liquidations','API 별도 Connection required']];$('dataSources').innerHTML=list.map(([n,v])=>`<div class="indicator"><strong>${escapeHTML(n)}</strong><span>${escapeHTML(v)}</span></div>`).join('')}
async function refreshAll(notify=false){if(refreshBusy)return;refreshBusy=true;$('networkStatus').textContent='데이터 Fetching…';try{const shouldHistory=Date.now()-lastHistoryRefresh>(history.length?12*3600000:15*60000);const jobs=[livePriceConnected?Promise.resolve():fetchPrice(),fetchFear(),fetchDerivatives(),refreshBlockHeight(),refreshInstitutional()];if(shouldHistory){lastHistoryRefresh=Date.now();jobs.push(fetchHistory(false))}await Promise.allSettled(jobs);$('networkStatus').textContent='Checked at '+new Date().toLocaleTimeString('ko-KR')+' · according to provider frequency';$('networkStatus').classList.add('ok');renderSources();animateLiveUpdate();if(notify)toast('외부 데이터 재Checked at 완료. 각 카드의 기준 days을 확인해 줘.')}finally{refreshBusy=false}}
function download(name,content,mime){const blob=new Blob([content],{type:mime+';charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}function downloadBackup(){download('cycle-terminal-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify({app:'cycle-terminal',version:2,savedAt:new Date().toISOString(),state},null,2),'application/json')}
async function restoreBackup(e){const f=e.target.files?.[0];if(!f)return;try{const raw=JSON.parse(await f.text());if(raw.app!=='cycle-terminal'||raw.version!==2||!raw.state||!Array.isArray(raw.state.charts)||!Array.isArray(raw.state.journal)||!Array.isArray(raw.state.history))throw Error('Unsupported backup file.');if(!confirm('Replace existing local data with this backup?'))return;state={...defaults(),...raw.state,strategy:{...defaults().strategy,...raw.state.strategy}};history=normalizeHistory(state.history);historySource=state.historySource||'';if(!persist())return;location.reload()}catch(err){toast('Restore failed: '+err.message)}finally{e.target.value=''}}
function restoreChecks(){document.querySelectorAll('[data-check]').forEach(x=>{x.checked=!!state.checks?.[x.dataset.check];x.addEventListener('change',()=>{state.checks[x.dataset.check]=x.checked;persist()})})}

// Community: verified public profiles through the official X embed, plus live-source RSS.
const LEADERS=[['Michael Saylor','saylor'],['Cathie Wood','CathieDWood'],['Balaji Srinivasan','balajis'],['Eric Balchunas','EricBalchunas'],['Bitcoin Magazine','BitcoinMagazine']];
let activeLeader='saylor',communityTab='all',newsItems=[],newsPending=false,newsEverLoaded=false;
function renderCommunity(){const tabs=$('leaderTabs');if(!tabs)return;tabs.replaceChildren();for(const [label,handle] of LEADERS){const b=document.createElement('button');b.textContent=label;b.className=activeLeader===handle?'selected':'';b.onclick=()=>{activeLeader=handle;renderCommunity()};tabs.append(b)}const x=$('xTimeline');if(x.dataset.handle!==activeLeader){x.dataset.handle=activeLeader;x.replaceChildren();const link=document.createElement('a');link.className='twitter-timeline';link.href='https://twitter.com/'+activeLeader;link.dataset.theme='dark';link.dataset.height='610';link.dataset.chrome='noheader nofooter transparent';link.textContent='@'+activeLeader+' 공 entries 게시물 보기';x.append(link);const fallback=document.createElement('a');fallback.href='https://x.com/'+activeLeader;fallback.target='_blank';fallback.rel='noopener noreferrer';fallback.className='x-fallback';fallback.textContent='Open @'+activeLeader+' original posts ↗';x.append(fallback);if(window.twttr?.widgets?.load)window.twttr.widgets.load(x);else if(!document.getElementById('x-embed-script')){const sc=document.createElement('script');sc.id='x-embed-script';sc.async=true;sc.src='https://platform.twitter.com/widgets.js';document.head.append(sc)}}const xOn=communityTab!=='news',newsOn=communityTab!=='x';$('communityXPanel').classList.toggle('hidden',!xOn);$('communityNewsPanel').classList.toggle('hidden',!newsOn);document.querySelectorAll('[data-community-tab]').forEach(b=>b.classList.toggle('active',b.dataset.communityTab===communityTab));renderNews();if(!newsEverLoaded&&!newsPending)fetchCommunityNews()}
function renderNews(){const list=$('newsTimeline');if(!list)return;list.replaceChildren();if(!newsItems.length){const empty=document.createElement('div');empty.className='community-empty';empty.textContent=newsPending?'실제 기사 제목과 발행시각 Fetching…':'News feed unavailable. Open the original publications below.';list.append(empty);return}for(const item of newsItems){const a=document.createElement('a');a.className='news-entry';a.href=item.link;a.target='_blank';a.rel='noopener noreferrer';const meta=document.createElement('div');meta.className='news-meta';meta.textContent=item.source+' · '+(item.date?new Date(item.date).toLocaleString('ko-KR'):'Publication time unavailable');const title=document.createElement('strong');title.textContent=item.title;const more=document.createElement('span');more.textContent='Read original ↗';a.append(meta,title,more);list.append(a)}}
async function fetchCommunityNews(){if(newsPending)return;newsPending=true;newsEverLoaded=true;$('newsStatus').textContent='Fetching';renderNews();try{const feeds=[['Cointelegraph','https://cointelegraph.com/rss'],['CoinDesk','https://www.coindesk.com/arc/outboundfeeds/rss/']];const results=await Promise.allSettled(feeds.map(async ([source,url])=>{const response=await fetch('https://proxy.cors.dev/'+url,{cache:'no-store'});if(!response.ok)throw Error('RSS '+response.status);const xml=new DOMParser().parseFromString(await response.text(),'application/xml');if(xml.querySelector('parsererror'))throw Error('Invalid RSS response');return [...xml.querySelectorAll('item')].slice(0,18).map(node=>({title:node.querySelector('title')?.textContent?.trim()||'',link:node.querySelector('link')?.textContent?.trim()||'',date:node.querySelector('pubDate')?.textContent?.trim()||'',source}))}));newsItems=results.flatMap(r=>r.status==='fulfilled'?r.value:[]).filter(x=>x.title&&/^https:\/\//.test(x.link)).sort((a,b)=>(Date.parse(b.date)||0)-(Date.parse(a.date)||0)).slice(0,30);if(!newsItems.length)throw Error('News providers are unavailable');$('newsStatus').textContent=newsItems.length+' records · 공 entries RSS'}catch(e){newsItems=[];$('newsStatus').textContent='External RSS access restricted'}finally{newsPending=false;renderNews()}}

function initCommunity(){document.querySelectorAll('[data-community-tab]').forEach(b=>b.onclick=()=>{communityTab=b.dataset.communityTab;renderCommunity()});}
// A subtle value-update motion, never a simulated tick/price.
function animateLiveUpdate(){for(const id of ['btcPrice','btcChange','fearScore','sentFear','sentDelta','fundingValue','oiValue','cycleDays','cycleReturn']){const el=$(id);if(!el)continue;const value=el.textContent;if(el.dataset.previousLiveValue!==value){if(el.dataset.previousLiveValue!==undefined){el.classList.remove('value-updated');void el.offsetWidth;el.classList.add('value-updated')}el.dataset.previousLiveValue=value}}}



let liveInstitution=null;
function safeMetric(v){return Number.isFinite(Number(v))?Number(v):null}
function readInstitutionSettings(){try{const u=localStorage.getItem('ct-institution-endpoint-'+(window.__CT_ACCOUNT_ID__||'guest'));const f=$('institutionEndpoint');if(f)f.value=u||'';return u||''}catch(e){return ''}}
async function refreshInstitutional(){const url=readInstitutionSettings();if(!url){fetched.institution='Dated snapshot · custom API not connected';renderInstitutional();return}try{const parsed=new URL(url);if(parsed.protocol!=='https:')throw Error('HTTPS endpoints only');const d=await jsonGet(parsed.href,14000);if(!d||typeof d!=='object'||typeof d.asOf!=='string'||!/^\d{4}-\d{2}-\d{2}/.test(d.asOf))throw Error('Missing asOf field');const etf=Array.isArray(d.etfFlows)?d.etfFlows.filter(x=>/^\d{4}-\d{2}-\d{2}$/.test(String(x.date))&&safeMetric(x.netMillionUsd)!==null).map(x=>[x.date,Number(x.netMillionUsd)]).sort((a,b)=>a[0].localeCompare(b[0])).slice(-120):null;const categories=d.treasuryCategories&&typeof d.treasuryCategories==='object'?Object.entries(d.treasuryCategories).filter(([,n])=>safeMetric(n)!==null&&Number(n)>=0).map(([k,n])=>[k,Number(n)]):null;const weekly=d.weeklyChanges&&typeof d.weeklyChanges==='object'?Object.entries(d.weeklyChanges).filter(([,n])=>safeMetric(n)!==null).map(([k,n])=>[k,Number(n)]):null;if(!etf?.length&&!categories?.length&&!weekly?.length)throw Error('유효한 ETF/보유량 데이터 None');liveInstitution={etf,categories,weekly,asOf:d.asOf,receivedAt:Date.now(),source:d.source||parsed.hostname};fetched.institution='Connected · source date '+d.asOf;renderInstitutional()}catch(e){fetched.institution='Connection failed · '+e.message;renderInstitutional()}renderSources()}
function initInstitutionEndpoint(){const input=$('institutionEndpoint'),save=$('saveInstitutionEndpoint');if(!input||!save)return;input.value=readInstitutionSettings();save.onclick=()=>{const value=input.value.trim();if(value){try{const u=new URL(value);if(u.protocol!=='https:')throw Error('HTTPS');}catch(e){toast('Enter an HTTPS JSON endpoint.');return}}try{if(value)localStorage.setItem('ct-institution-endpoint-'+(window.__CT_ACCOUNT_ID__||'guest'),value);else localStorage.removeItem('ct-institution-endpoint-'+(window.__CT_ACCOUNT_ID__||'guest'));liveInstitution=null;toast('Institutional endpoint saved.');refreshInstitutional()}catch(e){toast('Unable to save.')}}}

